// 題庫：上傳 Word 自動解析題目，並自動判斷難度（簡單 / 中等 / 困難）
// 使用：選單 →「匯入更新檔」→ 選這個檔案 → 再到「同步」→「上傳到雲端」
window.registerUpdate("題庫：上傳 Word 解析匯入題目＋自動判斷難度");
(function () {
  if (window.__bankWord) return;
  const COLOR = { 簡單: "#10b981", 中等: "#f59e0b", 困難: "#ef4444" };
  const strip = s => String(s).replace(/[\u0001\u0002]/g, "");

  // ── 難度：Word 裡有標示就照標示，沒有就用規則估計 ──
  function normDiff(s) {
    s = String(s || "").replace(/[\s【】\[\]（）()]/g, "");
    if (/^(簡單|容易|易|基礎|初級|入門|easy|★)$/i.test(s)) return "簡單";
    if (/^(中等|中|普通|適中|中級|medium|★★)$/i.test(s)) return "中等";
    if (/^(困難|難|進階|高級|高階|hard|★★★)$/i.test(s)) return "困難";
    return "";
  }
  function judge(q) {
    const t = q.text.replace(/（圖片請見 Word 試卷）/g, ""), os = q.options.map(o => o.text);
    const len = t.replace(/\s/g, "").length, nums = (t.match(/\d+(?:\.\d+)?/g) || []).length;
    let s = len > 120 ? 3 : len > 60 ? 2 : len > 30 ? 1 : 0;           // 題幹長度
    s += nums >= 4 ? 3 : nums >= 2 ? 2 : 0;                              // 題目給的數字越多越像計算題
    if (nums >= 2 && /計算|求|多少|幾倍|幾個|比值|平均|總和|共需|至少|至多/.test(t)) s += 1.5;
    if (/[=＝√∫Σπ^²³×÷±≤≥∠°]|\b(sin|cos|tan|log)\b|\d\s*\/\s*\d/i.test(t)) s += 1.5;   // 公式
    if (os.length && os.filter(o => /\d/.test(o) && !/[\u4e00-\u9fff]/.test(o)).length >= os.length * 0.75) s += 1;   // 選項是數值
    if (/下列.*(錯誤|不正確|不是|何者非|除外|不包括|不屬於|不能|不可)|(錯誤|不正確|除外|不包括)的?是/.test(t)) s += 1.5;   // 反向題
    if (os.filter(o => /[甲乙丙丁①②③④].*[甲乙丙丁①②③④]/.test(o)).length >= 2) s += 2;   // 組合選項
    if (os.some(o => /以上皆|皆正確|皆非|皆對|皆是/.test(o))) s += 1;
    const avg = os.reduce((a, o) => a + o.length, 0) / (os.length || 1);
    s += avg > 50 ? 2 : avg > 25 ? 1 : 0;                                // 選項很長
    const el = (q.explanation || "").length; s += el > 200 ? 2 : el > 80 ? 1 : 0;   // 解析很長
    if (len <= 25 && !nums && /稱為|是指|指的是|叫做|單位|符號|代表|名稱|俗稱|定義|屬於|全名|縮寫/.test(t)) s -= 1.5;   // 純記憶題
    return s <= 1.5 ? "簡單" : s >= 5 ? "困難" : "中等";
  }

  // ── Word → 文字行（保留粗體/底線標記，表格儲存格以空白分隔）──
  function toLines(html) {
    const t = html.replace(/<img[^>]*>/gi, "（圖片請見 Word 試卷）")
      .replace(/<(strong|u)>/gi, "\u0001").replace(/<\/(strong|u)>/gi, "\u0002")
      .replace(/<br\s*\/?>/gi, "\n").replace(/<\/(td|th)>/gi, " ")
      .replace(/<\/(p|h[1-6]|li|tr|div|table)>/gi, "\n").replace(/<[^>]+>/g, "");
    const ta = document.createElement("textarea"); ta.innerHTML = t;
    return ta.value.replace(/\r/g, "").split("\n").map(l => l.replace(/[ \t\u00a0　]+/g, " ").trim()).filter(Boolean);
  }

  const OPT = /^(?:[（(]\s*([A-Ea-e])\s*[)）]|([A-Ea-e])\s*[.．、)）])\s*(.*)$/;
  function splitOpts(line) {   // 一行有多個選項：(A)1 (B)2 (C)3 (D)4
    const f = line.match(OPT); if (!f) return null;
    const idx = [0]; let from = 1;
    for (let k = (f[1] || f[2]).toUpperCase().charCodeAt(0) + 1; k <= 69; k++) {
      const ch = String.fromCharCode(k);
      const m = new RegExp("[（(]\\s*" + ch + "\\s*[)）]|[\\s　]" + ch + "\\s*[.．、]", "i").exec(line.slice(from));
      if (!m) break;
      const at = from + m.index + (/^[\s　]/.test(m[0]) ? 1 : 0);
      idx.push(at); from = at + 1;
    }
    return idx.map((p, i) => line.slice(p, idx[i + 1]).trim());
  }
  function qStart(line) {
    let m = line.match(/^[（(]\s*([A-Ea-e]?)\s*[)）]\s*(?:Q\s*)?(\d+)\s*[.．、)）](?!\d)\s*(.*)$/i);   // ( B ) 1. 題目
    if (m) return { no: +m[2], text: m[3], ans: m[1].toUpperCase() };
    m = line.match(/^(?:Q\s*)?(\d+)\s*[.．、)）](?!\d)\s*(.*)$/i) || line.match(/^第\s*(\d+)\s*題\s*[.．、:：]?\s*(.*)$/);
    return m ? { no: +m[1], text: m[2], ans: "" } : null;
  }

  function parse(lines) {
    const head = /^(第\s*\d+\s*題\s*$|\d+\s*[.．、]\s*答案|【二】|參考答案|答案與|解答\s*$|答案\s*$)/;
    let ai = lines.findIndex(l => head.test(strip(l)));
    if (ai < 0) ai = lines.length;
    const qs = []; let cur = null, mode = "", m;
    lines.slice(0, ai).forEach(raw => {
      const line = strip(raw), st = qStart(line);
      if (st && st.no === (cur ? cur.no + 1 : 1) || st && st.no === 1) {
        cur = { no: st.no, text: st.text, options: [], answer: st.ans, explanation: "", diff: "" };
        qs.push(cur); mode = "q"; return;
      }
      if (!cur) return;
      if ((m = line.match(/^[【\[]?(?:正確)?(?:答案|解答|正解)[】\]]?\s*[:：]?\s*[（(]?\s*([A-Ea-e])/))) { cur.answer = m[1].toUpperCase(); mode = "a"; return; }
      if ((m = line.match(/^[【\[]?(?:解析|詳解|說明)[】\]]?\s*[:：]?\s*(.*)$/))) { cur.explanation = m[1]; mode = "e"; return; }
      if ((m = line.match(/^[【\[]?難度[】\]]?\s*[:：]?\s*(.+)$/))) { cur.diff = normDiff(m[1]); mode = "d"; return; }
      const parts = mode === "e" ? null : splitOpts(line);
      if (parts) {
        parts.forEach(p => { const o = p.match(OPT); cur.options.push({ letter: (o[1] || o[2]).toUpperCase(), text: o[3], marked: parts.length === 1 && raw.indexOf("\u0001") >= 0 }); });
        mode = "o"; return;
      }
      if (mode === "e") cur.explanation += "\n" + line;
      else if (mode === "o" && cur.options.length) cur.options[cur.options.length - 1].text += " " + line;
      else if (mode === "q") cur.text += "\n" + line;
    });
    // 檔案最後的「答案區」（第N題 / N.答案 / 1.A 2.B 3.C …）
    const tail = lines.slice(ai).map(strip), tt = tail.join("\n"), marks = [], re = /(?:^|\n)(?:第\s*(\d+)\s*題|(\d+)\s*[.．、]\s*(?=答案))/g;
    while ((m = re.exec(tt)) !== null) marks.push({ no: +(m[1] || m[2]), start: m.index + m[0].length });
    marks.forEach((mk, i) => {
      const b = tt.slice(mk.start, i + 1 < marks.length ? marks[i + 1].start : tt.length), q = qs.find(x => x.no === mk.no);
      const am = b.match(/答案\s*[】\]:：]?\s*[（(]?\s*([A-Ea-e])/), em = b.match(/解析\s*[】\]:：]?\s*([\s\S]*)$/);
      if (!q) return;
      if (am) q.answer = am[1].toUpperCase();
      if (em) q.explanation = em[1].replace(/\n+/g, " ").trim();
    });
    tail.filter(l => /^(?:\d+\s*[.．、:：)）\-]?\s*[（(]?[A-Ea-e][)）]?\s*)+$/.test(l)).forEach(l => {
      const r = /(\d+)\s*[.．、:：)）\-]?\s*[（(]?([A-Ea-e])[)）]?/g; let p;
      while ((p = r.exec(l)) !== null) { const q = qs.find(x => x.no === +p[1]); if (q && !q.answer) q.answer = p[2].toUpperCase(); }
    });
    // 整理
    return qs.filter(q => q.options.length >= 2).map(q => {
      if (!q.answer) { const mk = q.options.filter(o => o.marked); if (mk.length === 1) q.answer = mk[0].letter; }   // 只有一個選項粗體/底線 → 當答案
      const ai2 = q.options.findIndex(o => o.letter === q.answer);
      let text = q.text.trim(), diff = q.diff;
      const tg = text.match(/[【\[（(]\s*(簡單|中等|困難)\s*[】\]）)]/);
      if (tg) { if (!diff) diff = tg[1]; text = text.replace(tg[0], "").trim(); }
      const out = {
        text: text.slice(0, 1000),
        options: q.options.slice(0, 6).map((o, k) => ({ letter: "ABCDEF"[k], text: o.text.trim().slice(0, 300) })),
        answer: ai2 >= 0 ? "ABCDEF"[ai2] : "", explanation: q.explanation.trim().slice(0, 1000)
      };
      out.difficulty = diff || judge(out); out.byTag = !!diff;
      return out;
    });
  }

  // ── 預覽視窗 ──
  let pending = [];
  function ensureUi() {
    if (!document.getElementById("bwFile")) {
      document.body.insertAdjacentHTML("beforeend", `<input type="file" id="bwFile" accept=".docx" style="display:none">
        <div id="bankWordModal" class="modal"><div class="modal-content" style="max-width:860px;">
          <h3 style="margin-top:0;">📄 Word 匯入預覽</h3><div id="bwInfo" class="eco-sub" style="margin-bottom:10px;"></div>
          <div id="bwList" style="max-height:55vh; overflow:auto;"></div>
          <div style="text-align:right; margin-top:14px;">
            <button class="btn btn-secondary" type="button" onclick="window.closeModal('bankWordModal')">取消</button>
            <button class="btn" type="button" style="background:#10b981;" onclick="window.bankWordRun()">匯入</button></div></div></div>`);
      document.getElementById("bwFile").addEventListener("change", onFile);
    }
    const ex = document.getElementById("bqExplain");
    if (ex && !document.getElementById("bqDiff")) ex.closest(".form-group").insertAdjacentHTML("afterend",
      `<div class="form-group"><label>難度</label><select id="bqDiff"><option value="auto">自動判斷（依內容）</option><option>簡單</option><option>中等</option><option>困難</option></select></div>`);
  }
  async function onFile(ev) {
    const f = ev.target.files[0]; ev.target.value = "";
    if (!f) return;
    if (!/\.docx$/i.test(f.name)) return alert("只支援 .docx（舊版 .doc 請在 Word 另存成 .docx）。");
    if (typeof mammoth === "undefined") return alert("解析元件還沒載入，請檢查網路後重新整理。");
    try {
      const r = await mammoth.convertToHtml({ arrayBuffer: await f.arrayBuffer() }, { styleMap: ["u => u"] });
      pending = parse(toLines(r.value));
      if (!pending.length) return alert("沒有解析到題目。\n請確認題目有「1.」編號、選項有 (A)(B)(C)(D)，答案寫「答案：B」或放在檔案最後。" + (/<ol/i.test(r.value) ? "\n\n偵測到 Word 使用「自動編號」，編號不會被讀到，請改成手動輸入的編號。" : ""));
      showPreview(f.name);
    } catch (e) { alert("Word 解析失敗：" + e.message); }
  }
  function showPreview(name) {
    const u = bankFind(bankState.unitId), img = pending.filter(q => /圖片請見/.test(q.text)).length, noAns = pending.filter(q => !q.answer).length;
    document.getElementById("bwInfo").innerHTML = `「${esc(name)}」→ 匯入到「${esc(u.name)}」，共解析 ${pending.length} 題。難度是依題目內容自動估計的，可在下方逐題修改。`
      + (noAns ? `<br>⚠️ ${noAns} 題找不到答案，請在「答案」欄選好，沒選的不會匯入。` : "")
      + (img ? `<br>🖼️ ${img} 題含圖片，圖片無法存進題庫（題目裡有標註）。` : "");
    document.getElementById("bwList").innerHTML = pending.map((q, i) => `<div class="exam-q" style="padding:8px 10px;">
      <div class="exam-q-title"><b>${i + 1}.</b> <span title="${esc(q.text)}">${esc(q.text.replace(/\n/g, " ").slice(0, 70))}${q.text.length > 70 ? "…" : ""}</span></div>
      <div style="display:flex; gap:12px; flex-wrap:wrap; margin-top:6px; font-size:14px;">
        <label>答案 <select data-bw="a${i}"><option value="">（不匯入）</option>${q.options.map(o => `<option ${o.letter === q.answer ? "selected" : ""}>${o.letter}</option>`).join("")}</select></label>
        <label>難度 <select data-bw="d${i}">${["簡單", "中等", "困難"].map(d => `<option ${d === q.difficulty ? "selected" : ""}>${d}</option>`).join("")}</select>${q.byTag ? "（Word 標示）" : "（自動）"}</label></div></div>`).join("");
    window.openModal("bankWordModal");
  }
  window.bankWordRun = function () {
    if (!isAdmin) return;
    const u = bankFind(bankState.unitId); if (!u) return;
    const take = [], cnt = { 簡單: 0, 中等: 0, 困難: 0 }; let skip = 0;
    pending.forEach((q, i) => {
      const a = document.querySelector(`[data-bw="a${i}"]`).value, d = document.querySelector(`[data-bw="d${i}"]`).value;
      if (!a) return skip++;
      take.push({ id: bankNewId("q_"), text: q.text, options: q.options, answer: a, explanation: q.explanation, difficulty: d }); cnt[d]++;
    });
    const room = BANK_MAX_PER_UNIT - u.questions.length;
    if (!take.length) return alert("沒有可匯入的題目（每題都要有答案）。");
    if (room <= 0) return alert(`這個單元已有 ${BANK_MAX_PER_UNIT} 題，無法再新增。`);
    const add = take.slice(0, room);
    u.questions.push(...add); bankSave();
    window.closeModal("bankWordModal"); renderBank(); renderBankCard();
    alert(`✅ 已匯入 ${add.length} 題（簡單 ${cnt.簡單}／中等 ${cnt.中等}／困難 ${cnt.困難}）。` + (skip ? `\n${skip} 題沒有答案，已略過。` : "") + (add.length < take.length ? `\n超過單元上限，有 ${take.length - add.length} 題沒匯入。` : "") + "\n記得「上傳到雲端」。");
  };

  // ── 編輯題目時保留／設定難度 ──
  const oOpen = window.bankOpenQ, oSave = window.bankSaveQuestion;
  window.bankOpenQ = function (qid) {
    oOpen.apply(this, arguments);
    try { const u = bankFind(bankState.unitId), q = qid && u && u.questions.find(x => x.id === qid); document.getElementById("bqDiff").value = (q && q.difficulty) || "auto"; } catch (e) {}
  };
  window.bankSaveQuestion = function () {
    let u, n0, qid = bqCtx.qid, sel = "auto";
    try { u = bankFind(bqCtx.unitId); n0 = u.questions.length; sel = document.getElementById("bqDiff").value; } catch (e) {}
    oSave.apply(this, arguments);
    try {
      if (!u || modalShown("bankQEditModal")) return;   // 驗證沒過、視窗還開著 → 沒存成功
      const q = qid ? u.questions.find(x => x.id === qid) : (u.questions.length > n0 ? u.questions[u.questions.length - 1] : null);
      if (!q) return;
      q.difficulty = sel === "auto" ? judge(q) : sel;
      bankSave(); renderBank();
    } catch (e) {}
  };

  // ── 在題庫畫面加按鈕、難度標籤、難度統計 ──
  function decorate() {
    const body = document.getElementById("bankBody"); if (!body) return;
    try {
      const u = bankState.view !== "units" ? bankFind(bankState.unitId) : null; if (!u) return;
      if (bankState.view === "unit") {
        const imp = body.querySelector('button[onclick*="bankOpenImport"]');
        if (isAdmin && imp && !body.querySelector("#bwBtn")) imp.insertAdjacentHTML("afterend", ` <button id="bwBtn" class="btn" type="button" style="padding:4px 10px; font-size:13px; background:#4f46e5;" onclick="window.bankWordPick()">📄 上傳 Word</button>`);
        const c = body.querySelector(".bank-count");
        if (c && !body.querySelector("#bwStat") && u.questions.some(q => q.difficulty))
          c.insertAdjacentHTML("afterend", `<div id="bwStat" class="eco-sub" style="margin-top:6px;">${["簡單", "中等", "困難"].map(d => `<span style="color:${COLOR[d]}; font-weight:700;">${d} ${u.questions.filter(q => q.difficulty === d).length}</span>`).join("　")}</div>`);
      } else {
        body.querySelectorAll(".exam-q").forEach((el, i) => {
          const q = u.questions[i], t = el.querySelector(".exam-q-title");
          if (q && q.difficulty && t && !t.querySelector(".bw-badge")) t.insertAdjacentHTML("afterbegin", `<span class="bw-badge" style="background:${COLOR[q.difficulty]}; color:#fff; font-size:12px; padding:1px 8px; border-radius:10px; margin-right:6px;">${q.difficulty}</span>`);
        });
      }
    } catch (e) {}
  }
  window.bankWordPick = function () {
    if (!isAdmin) return alert("只有管理員可以匯入題目。");
    ensureUi(); document.getElementById("bwFile").click();
  };

  window.__bankWord = { parse, judge, toLines };
  ensureUi();
  const body = document.getElementById("bankBody");
  if (body) { new MutationObserver(decorate).observe(body, { childList: true }); decorate(); }
})();

// 考試區：管理員在「查看全部考卷」每份考卷旁多一個 🗑️ 刪除 按鈕
// 使用：選單 →「匯入更新檔」→ 選這個檔案 → 再到「同步」→「上傳到雲端」
window.registerUpdate("考試區：每份考卷加上刪除按鈕（管理員）");
(function () {
  if (window.__examZoneDel) return;
  window.__examZoneDel = true;

  function flat() {   // 跟 renderExamZone 一樣的順序：科目 → 單元 → 考卷（空單元跳過）
    const out = [], qz = rawDb.quizzes || {};
    Object.keys(qz).forEach(sub => Object.keys(qz[sub] || {}).forEach(topic =>
      (qz[sub][topic] || []).forEach((item, i) => out.push({ sub, topic, i, item }))));
    return out;
  }

  function decorate() {
    const box = document.getElementById("examZoneBody");
    if (!box || typeof isAdmin === "undefined" || !isAdmin) return;
    try {
      const list = flat();
      box.querySelectorAll(".exam-q").forEach((el, k) => {
        const e = list[k], bar = el.querySelector('div[style*="flex-shrink"]');
        if (!e || !bar || bar.querySelector(".ez-del")) return;
        const b = document.createElement("button");
        b.type = "button"; b.className = "btn btn-danger ez-del"; b.textContent = "🗑️ 刪除";
        b.style.cssText = "margin-left:6px;";
        b.onclick = () => window.examZoneDelete(e.sub, e.topic, e.i, String(e.item.id));
        bar.appendChild(b);
      });
    } catch (err) {}
  }

  window.examZoneDelete = function (sub, topic, i, id) {
    if (!isAdmin) return alert("只有管理員可以刪除考卷。");
    const arr = rawDb.quizzes && rawDb.quizzes[sub] && rawDb.quizzes[sub][topic];
    if (!arr) return;
    let idx = arr[i] && String(arr[i].id) === id ? i : arr.findIndex(x => String(x.id) === id);   // 資料有變動時用代號重新找
    if (idx < 0) return alert("找不到這份考卷，可能已被刪除，請重新開啟考試區。");
    if (!confirm(`確定刪除考卷「${arr[idx].title}」嗎？\n（${sub} / ${topic}，無法復原）`)) return;
    arr.splice(idx, 1);
    saveDb();
    renderExamZone();
    try { renderExamGrid(); } catch (err) {}
    alert("✅ 已刪除。記得「上傳到雲端」，其他電腦才會同步。");
  };

  const box = document.getElementById("examZoneBody");
  if (box) { new MutationObserver(decorate).observe(box, { childList: true }); decorate(); }
})();

// 題庫：上傳 Word 自動解析題目，並自動判斷難度（簡單 / 中等 / 困難）
// 使用：選單 →「匯入更新檔」→ 選這個檔案 → 再到「同步」→「上傳到雲端」
(function(){
const BW_VER = "v3";
window.registerUpdate("題庫Word匯入 " + BW_VER + "：上傳 Word 解析匯入題目＋自動判斷難度＋考卷支援「(簡單) 1.」格式");
(function () {
  if (window.__bankWord && window.__bankWord.ver === "v3") return;
  // 若舊版已載入：移除舊版的檔案欄位與按鈕，改由本版接手
  ["bwFile","bwBtn","bwStat"].forEach(id => { const e = document.getElementById(id); if (e) e.remove(); });
  const COLOR = { 簡單: "#10b981", 中等: "#f59e0b", 困難: "#ef4444" };
  const strip = s => String(s).replace(/[\u0001\u0002]/g, "");

  // ── 難度：Word 裡有標示就照標示，沒有就用規則估計 ──
  function normDiff(s) {
    s = String(s || "").replace(/[\s【】\[\]（）()]/g, "");
    if (/^(簡單|容易|易|基礎|初級|入門|easy|★)$/i.test(s)) return "簡單";
    if (/^(中等|中|普通|適中|中級|medium|★★)$/i.test(s)) return "中等";
    if (/^(困難|難|進階|高級|高階|hard|★★★)$/i.test(s)) return "困難";
    return "";
  }
  function judge(q) {
    const t = q.text.replace(/（圖片請見 Word 試卷）/g, ""), os = q.options.map(o => o.text);
    const len = t.replace(/\s/g, "").length, nums = (t.match(/\d+(?:\.\d+)?/g) || []).length;
    let s = len > 120 ? 3 : len > 60 ? 2 : len > 30 ? 1 : 0;           // 題幹長度
    s += nums >= 4 ? 3 : nums >= 2 ? 2 : 0;                              // 題目給的數字越多越像計算題
    if (nums >= 2 && /計算|求|多少|幾倍|幾個|比值|平均|總和|共需|至少|至多/.test(t)) s += 1.5;
    if (/[=＝√∫Σπ^²³×÷±≤≥∠°]|\b(sin|cos|tan|log)\b|\d\s*\/\s*\d/i.test(t)) s += 1.5;   // 公式
    if (os.length && os.filter(o => /\d/.test(o) && !/[\u4e00-\u9fff]/.test(o)).length >= os.length * 0.75) s += 1;   // 選項是數值
    if (/下列.*(錯誤|不正確|不是|何者非|除外|不包括|不屬於|不能|不可)|(錯誤|不正確|除外|不包括)的?是/.test(t)) s += 1.5;   // 反向題
    if (os.filter(o => /[甲乙丙丁①②③④].*[甲乙丙丁①②③④]/.test(o)).length >= 2) s += 2;   // 組合選項
    if (os.some(o => /以上皆|皆正確|皆非|皆對|皆是/.test(o))) s += 1;
    const avg = os.reduce((a, o) => a + o.length, 0) / (os.length || 1);
    s += avg > 50 ? 2 : avg > 25 ? 1 : 0;                                // 選項很長
    const el = (q.explanation || "").length; s += el > 200 ? 2 : el > 80 ? 1 : 0;   // 解析很長
    if (len <= 25 && !nums && /稱為|是指|指的是|叫做|單位|符號|代表|名稱|俗稱|定義|屬於|全名|縮寫/.test(t)) s -= 1.5;   // 純記憶題
    return s <= 1.5 ? "簡單" : s >= 5 ? "困難" : "中等";
  }

  // ── Word → 文字行（保留粗體/底線標記，表格儲存格以空白分隔）──
  function toLines(html) {
    const t = html.replace(/<img[^>]*>/gi, "（圖片請見 Word 試卷）")
      .replace(/<(strong|u)>/gi, "\u0001").replace(/<\/(strong|u)>/gi, "\u0002")
      .replace(/<br\s*\/?>/gi, "\n").replace(/<\/(td|th)>/gi, " ")
      .replace(/<\/(p|h[1-6]|li|tr|div|table)>/gi, "\n").replace(/<[^>]+>/g, "");
    const ta = document.createElement("textarea"); ta.innerHTML = t;
    return ta.value.replace(/\r/g, "").split("\n").map(l => l.replace(/[ \t\u00a0　]+/g, " ").trim()).filter(Boolean);
  }

  const OPT = /^(?:[（(]\s*([A-Ea-e])\s*[)）]|([A-Ea-e])\s*[.．、)）])\s*(.*)$/;
  function splitOpts(line) {   // 一行有多個選項：(A)1 (B)2 (C)3 (D)4
    const f = line.match(OPT); if (!f) return null;
    const idx = [0]; let from = 1;
    for (let k = (f[1] || f[2]).toUpperCase().charCodeAt(0) + 1; k <= 69; k++) {
      const ch = String.fromCharCode(k);
      const m = new RegExp("[（(]\\s*" + ch + "\\s*[)）]|[\\s　]" + ch + "\\s*[.．、]", "i").exec(line.slice(from));
      if (!m) break;
      const at = from + m.index + (/^[\s　]/.test(m[0]) ? 1 : 0);
      idx.push(at); from = at + 1;
    }
    return idx.map((p, i) => line.slice(p, idx[i + 1]).trim());
  }
  function qStart(line) {
    let m = line.match(/^[（(]\s*(簡單|中等|困難|易|中|難)\s*[)）]\s*(?:Q\s*)?(\d+)\s*[.．、)）](?!\d)\s*(.*)$/i);   // (簡單) 1. 題目
    if (m) return { no: +m[2], text: m[3], ans: "", diff: normDiff(m[1]) };
    m = line.match(/^[（(]\s*([A-Ea-e]?)\s*[)）]\s*(?:Q\s*)?(\d+)\s*[.．、)）](?!\d)\s*(.*)$/i);   // ( B ) 1. 題目
    if (m) return { no: +m[2], text: m[3], ans: m[1].toUpperCase() };
    m = line.match(/^(?:Q\s*)?(\d+)\s*[.．、)）](?!\d)\s*(.*)$/i) || line.match(/^第\s*(\d+)\s*題\s*[.．、:：]?\s*(.*)$/);
    return m ? { no: +m[1], text: m[2], ans: "" } : null;
  }

  function parse(lines) {
    const head = /^(第\s*\d+\s*題\s*$|第\s*\d+\s*題[^\n]{0,12}答案|\d+\s*[.．、]\s*答案|【二】|參考答案|答案與|解答\s*$|答案\s*$|[【\[][^】\]]*(?:解答|解析|答案)[^】\]]*[】\]]\s*$)/;
    let ai = lines.findIndex(l => head.test(strip(l)));
    if (ai < 0) ai = lines.length;
    const qs = []; let cur = null, mode = "", m;
    lines.slice(0, ai).forEach(raw => {
      const line = strip(raw), st = qStart(line);
      if (st && st.no === (cur ? cur.no + 1 : 1) || st && st.no === 1) {
        cur = { no: st.no, text: st.text, options: [], answer: st.ans, explanation: "", diff: st.diff || "" };
        qs.push(cur); mode = "q"; return;
      }
      if (!cur) return;
      if ((m = line.match(/^[【\[]?(?:正確)?(?:答案|解答|正解)[】\]]?\s*[:：]?\s*[（(]?\s*([A-Ea-e])/))) { cur.answer = m[1].toUpperCase(); mode = "a"; return; }
      if ((m = line.match(/^[【\[]?(?:解析|詳解|說明)[】\]]?\s*[:：]?\s*(.*)$/))) { cur.explanation = m[1]; mode = "e"; return; }
      if ((m = line.match(/^[【\[]?難度[】\]]?\s*[:：]?\s*(.+)$/))) { cur.diff = normDiff(m[1]); mode = "d"; return; }
      const parts = mode === "e" ? null : splitOpts(line);
      if (parts) {
        parts.forEach(p => { const o = p.match(OPT); cur.options.push({ letter: (o[1] || o[2]).toUpperCase(), text: o[3], marked: parts.length === 1 && raw.indexOf("\u0001") >= 0 }); });
        mode = "o"; return;
      }
      if (mode === "e") cur.explanation += "\n" + line;
      else if (mode === "o" && cur.options.length) cur.options[cur.options.length - 1].text += " " + line;
      else if (mode === "q") cur.text += "\n" + line;
    });
    // 檔案最後的「答案區」（第N題 / N.答案 / 1.A 2.B 3.C …）
    const tail = lines.slice(ai).map(strip), tt = tail.join("\n"), marks = [], re = /(?:^|\n)(?:第\s*(\d+)\s*題|(\d+)\s*[.．、]\s*(?=答案))/g;
    while ((m = re.exec(tt)) !== null) marks.push({ no: +(m[1] || m[2]), start: m.index + m[0].length, at: m.index });
    // 每個段落（簡單/中等/困難）題號可能各自從 1 重新開始，而答案區用全部連續的題號 → 依「出現順序」或難度標籤對應
    const pick = (no, blk) => {
      const c = qs.filter(x => x.no === no);
      if (c.length === 1) return c[0];
      const tg = blk.match(/^\s*[（(]\s*(簡單|中等|困難)/);
      return c.length > 1 ? ((tg && c.find(x => x.diff === tg[1])) || qs[no - 1] || c[0]) : qs[no - 1];
    };
    marks.forEach((mk, i) => {
      const b = tt.slice(mk.start, i + 1 < marks.length ? marks[i + 1].at : tt.length), q = pick(mk.no, b);
      const am = b.match(/答案\s*[】\]:：]?\s*[（(]?\s*([A-Ea-e])/), em = b.match(/解析\s*[】\]:：]?\s*([\s\S]*)$/);
      if (!q) return;
      if (am) q.answer = am[1].toUpperCase();
      if (em) q.explanation = em[1].replace(/\n+/g, " ").trim();
    });
    tail.filter(l => /^(?:\d+\s*[.．、:：)）\-]?\s*[（(]?[A-Ea-e][)）]?\s*)+$/.test(l)).forEach(l => {
      const r = /(\d+)\s*[.．、:：)）\-]?\s*[（(]?([A-Ea-e])[)）]?/g; let p;
      while ((p = r.exec(l)) !== null) { const q = pick(+p[1], ""); if (q && !q.answer) q.answer = p[2].toUpperCase(); }
    });
    // 整理
    return qs.filter(q => q.options.length >= 2).map(q => {
      if (!q.answer) { const mk = q.options.filter(o => o.marked); if (mk.length === 1) q.answer = mk[0].letter; }   // 只有一個選項粗體/底線 → 當答案
      const ai2 = q.options.findIndex(o => o.letter === q.answer);
      let text = q.text.trim(), diff = q.diff;
      const tg = text.match(/[【\[（(]\s*(簡單|中等|困難)\s*[】\]）)]/);
      if (tg) { if (!diff) diff = tg[1]; text = text.replace(tg[0], "").trim(); }
      const out = {
        text: text.slice(0, 1000),
        options: q.options.slice(0, 6).map((o, k) => ({ letter: "ABCDEF"[k], text: o.text.trim().slice(0, 300) })),
        answer: ai2 >= 0 ? "ABCDEF"[ai2] : "", explanation: q.explanation.trim().slice(0, 1000)
      };
      out.difficulty = diff || judge(out); out.byTag = !!diff;
      return out;
    });
  }

  // ── 預覽視窗 ──
  let pending = [];
  function ensureUi() {
    if (!document.getElementById("bwFile")) {
      document.body.insertAdjacentHTML("beforeend", `<input type="file" id="bwFile" accept=".docx" style="display:none">
        <div id="bankWordModal" class="modal"><div class="modal-content" style="max-width:860px;">
          <h3 style="margin-top:0;">📄 Word 匯入預覽</h3><div id="bwInfo" class="eco-sub" style="margin-bottom:10px;"></div>
          <div id="bwList" style="max-height:55vh; overflow:auto;"></div>
          <div style="text-align:right; margin-top:14px;">
            <button class="btn btn-secondary" type="button" onclick="window.closeModal('bankWordModal')">取消</button>
            <button class="btn" type="button" style="background:#10b981;" onclick="window.bankWordRun()">匯入</button></div></div></div>`);
      document.getElementById("bwFile").addEventListener("change", onFile);
    }
    const ex = document.getElementById("bqExplain");
    if (ex && !document.getElementById("bqDiff")) ex.closest(".form-group").insertAdjacentHTML("afterend",
      `<div class="form-group"><label>難度</label><select id="bqDiff"><option value="auto">自動判斷（依內容）</option><option>簡單</option><option>中等</option><option>困難</option></select></div>`);
  }
  async function onFile(ev) {
    const f = ev.target.files[0]; ev.target.value = "";
    if (!f) return;
    if (!/\.docx$/i.test(f.name)) return alert("只支援 .docx（舊版 .doc 請在 Word 另存成 .docx）。");
    if (typeof mammoth === "undefined") return alert("解析元件還沒載入，請檢查網路後重新整理。");
    try {
      const r = await mammoth.convertToHtml({ arrayBuffer: await f.arrayBuffer() }, { styleMap: ["u => u"] });
      const ls = toLines(r.value); pending = parse(ls);
      if (!pending.length) return alert("（更新檔 " + BW_VER + "）沒有解析到題目。\n程式讀到 " + ls.length + " 行，前 4 行是：\n" + ls.slice(0, 4).map(strip).join("\n") + "\n\n請確認題目有「1.」編號、選項有 (A)(B)(C)(D)，答案寫「答案：B」或放在檔案最後。" + (/<ol/i.test(r.value) ? "\n\n偵測到 Word 使用「自動編號」，編號不會被讀到，請改成手動輸入的編號。" : ""));
      showPreview(f.name);
    } catch (e) { alert("Word 解析失敗：" + e.message); }
  }
  function showPreview(name) {
    const u = bankFind(bankState.unitId), img = pending.filter(q => /圖片請見/.test(q.text)).length, noAns = pending.filter(q => !q.answer).length;
    document.getElementById("bwInfo").innerHTML = `「${esc(name)}」→ 匯入到「${esc(u.name)}」，共解析 ${pending.length} 題。難度是依題目內容自動估計的，可在下方逐題修改。`
      + (noAns ? `<br>⚠️ ${noAns} 題找不到答案，請在「答案」欄選好，沒選的不會匯入。` : "")
      + (img ? `<br>🖼️ ${img} 題含圖片，圖片無法存進題庫（題目裡有標註）。` : "");
    document.getElementById("bwList").innerHTML = pending.map((q, i) => `<div class="exam-q" style="padding:8px 10px;">
      <div class="exam-q-title"><b>${i + 1}.</b> <span title="${esc(q.text)}">${esc(q.text.replace(/\n/g, " ").slice(0, 70))}${q.text.length > 70 ? "…" : ""}</span></div>
      <div style="display:flex; gap:12px; flex-wrap:wrap; margin-top:6px; font-size:14px;">
        <label>答案 <select data-bw="a${i}"><option value="">（不匯入）</option>${q.options.map(o => `<option ${o.letter === q.answer ? "selected" : ""}>${o.letter}</option>`).join("")}</select></label>
        <label>難度 <select data-bw="d${i}">${["簡單", "中等", "困難"].map(d => `<option ${d === q.difficulty ? "selected" : ""}>${d}</option>`).join("")}</select>${q.byTag ? "（Word 標示）" : "（自動）"}</label></div></div>`).join("");
    window.openModal("bankWordModal");
  }
  window.bankWordRun = function () {
    if (!isAdmin) return;
    const u = bankFind(bankState.unitId); if (!u) return;
    const take = [], cnt = { 簡單: 0, 中等: 0, 困難: 0 }; let skip = 0;
    pending.forEach((q, i) => {
      const a = document.querySelector(`[data-bw="a${i}"]`).value, d = document.querySelector(`[data-bw="d${i}"]`).value;
      if (!a) return skip++;
      take.push({ id: bankNewId("q_"), text: q.text, options: q.options, answer: a, explanation: q.explanation, difficulty: d }); cnt[d]++;
    });
    const room = BANK_MAX_PER_UNIT - u.questions.length;
    if (!take.length) return alert("沒有可匯入的題目（每題都要有答案）。");
    if (room <= 0) return alert(`這個單元已有 ${BANK_MAX_PER_UNIT} 題，無法再新增。`);
    const add = take.slice(0, room);
    u.questions.push(...add); bankSave();
    window.closeModal("bankWordModal"); renderBank(); renderBankCard();
    alert(`✅ 已匯入 ${add.length} 題（簡單 ${cnt.簡單}／中等 ${cnt.中等}／困難 ${cnt.困難}）。` + (skip ? `\n${skip} 題沒有答案，已略過。` : "") + (add.length < take.length ? `\n超過單元上限，有 ${take.length - add.length} 題沒匯入。` : "") + "\n記得「上傳到雲端」。");
  };

  // ── 編輯題目時保留／設定難度 ──
  const oOpen = window.bankOpenQ, oSave = window.bankSaveQuestion;
  window.bankOpenQ = function (qid) {
    oOpen.apply(this, arguments);
    try { const u = bankFind(bankState.unitId), q = qid && u && u.questions.find(x => x.id === qid); document.getElementById("bqDiff").value = (q && q.difficulty) || "auto"; } catch (e) {}
  };
  window.bankSaveQuestion = function () {
    let u, n0, qid = bqCtx.qid, sel = "auto";
    try { u = bankFind(bqCtx.unitId); n0 = u.questions.length; sel = document.getElementById("bqDiff").value; } catch (e) {}
    oSave.apply(this, arguments);
    try {
      if (!u || modalShown("bankQEditModal")) return;   // 驗證沒過、視窗還開著 → 沒存成功
      const q = qid ? u.questions.find(x => x.id === qid) : (u.questions.length > n0 ? u.questions[u.questions.length - 1] : null);
      if (!q) return;
      q.difficulty = sel === "auto" ? judge(q) : sel;
      bankSave(); renderBank();
    } catch (e) {}
  };

  // ── 在題庫畫面加按鈕、難度標籤、難度統計 ──
  function decorate() {
    const body = document.getElementById("bankBody"); if (!body) return;
    try {
      const u = bankState.view !== "units" ? bankFind(bankState.unitId) : null; if (!u) return;
      if (bankState.view === "unit") {
        const imp = body.querySelector('button[onclick*="bankOpenImport"]');
        if (isAdmin && imp && !body.querySelector("#bwBtn")) imp.insertAdjacentHTML("afterend", ` <button id="bwBtn" class="btn" type="button" style="padding:4px 10px; font-size:13px; background:#4f46e5;" onclick="window.bankWordPick()">📄 上傳 Word</button>`);
        const c = body.querySelector(".bank-count");
        if (c && !body.querySelector("#bwStat") && u.questions.some(q => q.difficulty))
          c.insertAdjacentHTML("afterend", `<div id="bwStat" class="eco-sub" style="margin-top:6px;">${["簡單", "中等", "困難"].map(d => `<span style="color:${COLOR[d]}; font-weight:700;">${d} ${u.questions.filter(q => q.difficulty === d).length}</span>`).join("　")}</div>`);
      } else {
        body.querySelectorAll(".exam-q").forEach((el, i) => {
          const q = u.questions[i], t = el.querySelector(".exam-q-title");
          if (q && q.difficulty && t && !t.querySelector(".bw-badge")) t.insertAdjacentHTML("afterbegin", `<span class="bw-badge" style="background:${COLOR[q.difficulty]}; color:#fff; font-size:12px; padding:1px 8px; border-radius:10px; margin-right:6px;">${q.difficulty}</span>`);
        });
      }
    } catch (e) {}
  }
  window.bankWordPick = function () {
    if (!isAdmin) return alert("只有管理員可以匯入題目。");
    ensureUi(); document.getElementById("bwFile").click();
  };

  // ── 線上考卷（題目與考試區）也改用這個解析器：支援「(簡單) 1.」、各段題號重新編號、「第N題（簡單）答案」 ──
  try {
    const origExam = parseExamLines;
    parseExamLines = function (lines) {
      let o = [], n = [];
      try { o = origExam(lines); } catch (e) {}
      try { n = parse(lines); } catch (e) {}
      const ok = a => a.filter(q => q.answer).length;
      if (n.length && (n.length > o.length || ok(n) > ok(o))) return n.map((q, i) => ({ no: i + 1, text: q.text, options: q.options, answer: q.answer, explanation: q.explanation }));
      return o;
    };
  } catch (e) {}

  window.__bankWord = { ver: "v3", parse, judge, toLines };
  ensureUi();
  const body = document.getElementById("bankBody");
  if (body) { new MutationObserver(decorate).observe(body, { childList: true }); decorate(); }
})();
})();

// 題庫：首頁「題庫」區的每個單元卡片加上 ✏️ 改名 / 🗑️ 刪除按鈕（只有管理員看得到）
// 使用：選單 →「匯入更新檔」→ 選這個檔案 → 再到「同步」→「上傳到雲端」
